194	    private void saveScrollPosition() {
195	        int firstItem = layoutManager.findFirstVisibleItemPosition();
196	        View firstItemView = layoutManager.findViewByPosition(firstItem);
197	        float topOffset;
198	        if(firstItemView == null) {
199	            topOffset = 0;
200	        } else {
201	            topOffset = firstItemView.getTop();
202	        }
203	
204	        SharedPreferences prefs = getActivity().getSharedPreferences(PREFS, Context.MODE_PRIVATE);
205	        SharedPreferences.Editor editor = prefs.edit();
206	        editor.putInt(PREF_SCROLL_POSITION, firstItem);
207	        editor.putFloat(PREF_SCROLL_OFFSET, topOffset);
208	        editor.commit();
209	    }
210	
211	    private void restoreScrollPosition() {
212	        SharedPreferences prefs = getActivity().getSharedPreferences(PREFS, Context.MODE_PRIVATE);
213	        int position = prefs.getInt(PREF_SCROLL_POSITION, 0);
214	        float offset = prefs.getFloat(PREF_SCROLL_OFFSET, 0.0f);
215	        if (position > 0 || offset > 0) {
216	            layoutManager.scrollToPositionWithOffset(position, (int) offset);
217	        }
218	    }
