378	    public View onCreateView(LayoutInflater inflater, ViewGroup container, Bundle savedInstanceState) {
379	        super.onCreateView(inflater, container, savedInstanceState);
380	        ((MainActivity) getActivity()).getSupportActionBar().setTitle(R.string.queue_label);
381	
382	        View root = inflater.inflate(R.layout.queue_fragment, container, false);
383	        infoBar = root.findViewById(R.id.info_bar);
384	        recyclerView = root.findViewById(R.id.recyclerView);
385	        RecyclerView.ItemAnimator animator = recyclerView.getItemAnimator();
386	        if (animator instanceof SimpleItemAnimator) {
387	            ((SimpleItemAnimator) animator).setSupportsChangeAnimations(false);
388	        }
389	        layoutManager = new LinearLayoutManager(getActivity());
390	        recyclerView.setLayoutManager(layoutManager);
391	        recyclerView.addItemDecoration(new HorizontalDividerItemDecoration.Builder(getActivity()).build());
392	        recyclerView.setHasFixedSize(true);
393	        registerForContextMenu(recyclerView);
394	
395	        itemTouchHelper = new ItemTouchHelper(
396	            new ItemTouchHelper.SimpleCallback(ItemTouchHelper.UP | ItemTouchHelper.DOWN, ItemTouchHelper.RIGHT) {
397	
398	                // Position tracking whilst dragging
399	                int dragFrom = -1;
400	                int dragTo = -1;
401	
402	                @Override
403	                public boolean onMove(RecyclerView recyclerView, RecyclerView.ViewHolder viewHolder, RecyclerView.ViewHolder target) {
404	                    int fromPosition = viewHolder.getAdapterPosition();
405	                    int toPosition = target.getAdapterPosition();
406	
407	                    // Update tracked position
408	                    if(dragFrom == -1) {
409	                        dragFrom =  fromPosition;
410	                    }
411	                    dragTo = toPosition;
412	
413	                    int from = viewHolder.getAdapterPosition();
414	                    int to = target.getAdapterPosition();
415	                    Log.d(TAG, "move(" + from + ", " + to + ") in memory");
416	                    if(from >= queue.size() || to >= queue.size()) {
417	                        return false;
418	                    }
419	                    queue.add(to, queue.remove(from));
420	                    recyclerAdapter.notifyItemMoved(from, to);
421	                    return true;
422	                }
423	
424	                @Override
425	                public void onSwiped(RecyclerView.ViewHolder viewHolder, int direction) {
426	                    if(subscription != null) {
427	                        subscription.unsubscribe();
428	                    }
429	                    final int position = viewHolder.getAdapterPosition();
430	                    Log.d(TAG, "remove(" + position + ")");
431	                    final FeedItem item = queue.get(position);
432	                    final boolean isRead = item.isPlayed();
433	                    DBWriter.markItemPlayed(FeedItem.PLAYED, false, item.getId());
434	                    DBWriter.removeQueueItem(getActivity(), item, true);
435	                    Snackbar snackbar = Snackbar.make(root, getString(R.string.marked_as_read_label), Snackbar.LENGTH_LONG);
436	                    snackbar.setAction(getString(R.string.undo), v -> {
437	                        DBWriter.addQueueItemAt(getActivity(), item.getId(), position, false);
438	                        if(!isRead) {
439	                            DBWriter.markItemPlayed(FeedItem.UNPLAYED, item.getId());
440	                        }
441	                    });
442	                    snackbar.show();
443	                }
444	
445	                @Override
446	                public boolean isLongPressDragEnabled() {
447	                    return !UserPreferences.isQueueLocked();
448	                }
449	
450	                @Override
451	                public boolean isItemViewSwipeEnabled() {
452	                    return !UserPreferences.isQueueLocked();
453	                }
454	
455	                @Override
456	                public void onSelectedChanged(RecyclerView.ViewHolder viewHolder,
457	                                              int actionState) {
458	                    // We only want the active item
459	                    if (actionState != ItemTouchHelper.ACTION_STATE_IDLE) {
460	                        if (viewHolder instanceof QueueRecyclerAdapter.ItemTouchHelperViewHolder) {
461	                            QueueRecyclerAdapter.ItemTouchHelperViewHolder itemViewHolder =
462	                                    (QueueRecyclerAdapter.ItemTouchHelperViewHolder) viewHolder;
463	                            itemViewHolder.onItemSelected();
464	                        }
465	                    }
466	
467	                    super.onSelectedChanged(viewHolder, actionState);
468	                }
469	                @Override
470	                public void clearView(RecyclerView recyclerView,
471	                                      RecyclerView.ViewHolder viewHolder) {
472	                    super.clearView(recyclerView, viewHolder);
473	
474	                    // Check if drag finished
475	                    if(dragFrom != -1 && dragTo != -1 && dragFrom != dragTo) {
476	                        reallyMoved(dragFrom, dragTo);
477	                    }
478	
479	                    dragFrom = dragTo = -1;
480	
481	                    if (viewHolder instanceof QueueRecyclerAdapter.ItemTouchHelperViewHolder) {
482	                        QueueRecyclerAdapter.ItemTouchHelperViewHolder itemViewHolder =
483	                                (QueueRecyclerAdapter.ItemTouchHelperViewHolder) viewHolder;
484	                        itemViewHolder.onItemClear();
485	                    }
486	                }
487	
488	                private void reallyMoved(int from, int to) {
489	                    // Write drag operation to database
490	                    Log.d(TAG, "Write to database move(" + from + ", " + to + ")");
491	                    DBWriter.moveQueueItem(from, to, true);
492	                }
493	            }
494	        );
495	        itemTouchHelper.attachToRecyclerView(recyclerView);
496	
497	        txtvEmpty = root.findViewById(android.R.id.empty);
498	        txtvEmpty.setVisibility(View.GONE);
499	        progLoading = root.findViewById(R.id.progLoading);
500	        progLoading.setVisibility(View.VISIBLE);
501	
502	        return root;
503	    }
