505	    private void onFragmentLoaded(final boolean restoreScrollPosition) {
506	        if (recyclerAdapter == null) {
507	            MainActivity activity = (MainActivity) getActivity();
508	            recyclerAdapter = new QueueRecyclerAdapter(activity, itemAccess,
509	                new DefaultActionButtonCallback(activity), itemTouchHelper);
510	            recyclerAdapter.setHasStableIds(true);
511	            recyclerView.setAdapter(recyclerAdapter);
512	        }
513	        if(queue == null || queue.size() == 0) {
514	            recyclerView.setVisibility(View.GONE);
515	            txtvEmpty.setVisibility(View.VISIBLE);
516	        } else {
517	            txtvEmpty.setVisibility(View.GONE);
518	            recyclerView.setVisibility(View.VISIBLE);
519	        }
520	
521	        if (restoreScrollPosition) {
522	            restoreScrollPosition();
523	        }
524	
525	        // we need to refresh the options menu because it sometimes
526	        // needs data that may have just been loaded.
527	        getActivity().supportInvalidateOptionsMenu();
528	
529	        refreshInfoBar();
530	    }
