532	    private void refreshInfoBar() {
533	        String info = queue.size() + getString(R.string.episodes_suffix);
534	        if(queue.size() > 0) {
535	            long timeLeft = 0;
536	            float playbackSpeed = Float.valueOf(UserPreferences.getPlaybackSpeed());
537	            for(FeedItem item : queue) {
538	                if(item.getMedia() != null) {
539	                    timeLeft +=
540	                            (long) ((item.getMedia().getDuration() - item.getMedia().getPosition())
541	                                    / playbackSpeed);
542	                }
543	            }
544	            info += " \u2022 ";
545	            info += getString(R.string.time_left_label);
546	            info += Converter.getDurationStringLocalized(getActivity(), timeLeft);
547	        }
548	        infoBar.setText(info);
549	    }
