496	    void markItemAsSeenWithUndo(FeedItem item) {
497	        if (item == null) {
498	            return;
499	        }
500	
501	        Log.d(TAG, "markItemAsSeenWithUndo(" + item.getId() + ")");
502	        if (subscription != null) {
503	            subscription.unsubscribe();
504	        }
505	        // we're marking it as unplayed since the user didn't actually play it
506	        // but they don't want it considered 'NEW' anymore
507	        DBWriter.markItemPlayed(FeedItem.UNPLAYED, item.getId());
508	
509	        final Handler h = new Handler(getActivity().getMainLooper());
510	        final Runnable r  = () -> {
511	            FeedMedia media = item.getMedia();
512	            if (media != null && media.hasAlmostEnded() && UserPreferences.isAutoDelete()) {
513	                DBWriter.deleteFeedMediaOfItem(getActivity(), media.getId());
514	            }
515	        };
516	
517	        Snackbar snackbar = Snackbar.make(getView(), getString(R.string.marked_as_seen_label),
518	                Snackbar.LENGTH_LONG);
519	        snackbar.setAction(getString(R.string.undo), v -> {
520	            DBWriter.markItemPlayed(FeedItem.NEW, item.getId());
521	            // don't forget to cancel the thing that's going to remove the media
522	            h.removeCallbacks(r);
523	        });
524	        snackbar.show();
525	        h.postDelayed(r, (int)Math.ceil(snackbar.getDuration() * 1.05f));
526	    }
