217	
218	            title.setText(item.getTitle());
219	            String pubDateStr = DateUtils.formatAbbrev(mainActivity.get(), item.getPubDate());
220	            int index = 0;
221	            if(countMatches(pubDateStr, ' ') == 1 || countMatches(pubDateStr, ' ') == 2) {
222	                index = pubDateStr.lastIndexOf(' ');
223	            } else if(countMatches(pubDateStr, '.') == 2) {
224	                index = pubDateStr.lastIndexOf('.');
225	            } else if(countMatches(pubDateStr, '-') == 2) {
226	                index = pubDateStr.lastIndexOf('-');
227	            } else if(countMatches(pubDateStr, '/') == 2) {
228	                index = pubDateStr.lastIndexOf('/');
229	            }
230	            if(index > 0) {
231	                pubDateStr = pubDateStr.substring(0, index+1).trim() + "\n" + pubDateStr.substring(index+1);
232	            }
233	            pubDate.setText(pubDateStr);
234	
235	            if (media != null) {
236	                final boolean isDownloadingMedia = DownloadRequester.getInstance().isDownloadingFile(media);
237	                FeedItem.State state = item.getState();
238	                if (isDownloadingMedia) {
239	                    progressLeft.setText(Converter.byteToString(itemAccess.getItemDownloadedBytes(item)));
240	                    if(itemAccess.getItemDownloadSize(item) > 0) {
241	                        progressRight.setText(Converter.byteToString(itemAccess.getItemDownloadSize(item)));
242	                    } else {
243	                        progressRight.setText(Converter.byteToString(media.getSize()));
244	                    }
245	                    progressBar.setProgress(itemAccess.getItemDownloadProgressPercent(item));
246	                    progressBar.setVisibility(View.VISIBLE);
247	                } else if (state == FeedItem.State.PLAYING
248	                    || state == FeedItem.State.IN_PROGRESS) {
249	                    if (media.getDuration() > 0) {
250	                        int progress = (int) (100.0 * media.getPosition() / media.getDuration());
251	                        progressBar.setProgress(progress);
252	                        progressBar.setVisibility(View.VISIBLE);
253	                        progressLeft.setText(Converter
254	                            .getDurationStringLong(media.getPosition()));
255	                        progressRight.setText(Converter.getDurationStringLong(media.getDuration()));
256	                    }
257	                } else {
258	                    if(media.getSize() > 0) {
259	                        progressLeft.setText(Converter.byteToString(media.getSize()));
260	                    } else if(NetworkUtils.isDownloadAllowed() && !media.checkedOnSizeButUnknown()) {
261	                        progressLeft.setText("{fa-spinner}");
262	                        Iconify.addIcons(progressLeft);
263	                        NetworkUtils.getFeedMediaSizeObservable(media)
264	                            .subscribe(
265	                                size -> {
266	                                    if (size > 0) {
267	                                        progressLeft.setText(Converter.byteToString(size));
268	                                    } else {
269	                                        progressLeft.setText("");
270	                                    }
271	                                }, error -> {
272	                                    progressLeft.setText("");
273	                                    Log.e(TAG, Log.getStackTraceString(error));
274	                                });
275	                    } else {
276	                        progressLeft.setText("");
277	                    }
278	                    progressRight.setText(Converter.getDurationStringLong(media.getDuration()));
279	                    progressBar.setVisibility(View.INVISIBLE);
280	                }
281	
282	                if(media.isCurrentlyPlaying()) {
283	                    container.setBackgroundColor(playingBackGroundColor);
284	                } else {
285	                    container.setBackgroundColor(normalBackGroundColor);
286	                }
287	            }
288	
289	            actionButtonUtils.configureActionButton(butSecondary, item, true);
290	            butSecondary.setFocusable(false);
291	            butSecondary.setTag(item);
292	            butSecondary.setOnClickListener(secondaryActionListener);
293	
294	            Glide.with(mainActivity.get())
