345	    private static int countMatches(final CharSequence str, final char ch) {
346	        if (TextUtils.isEmpty(str)) {
347	            return 0;
348	        }
349	        int count = 0;
350	        for (int i = 0; i < str.length(); i++) {
351	            if (ch == str.charAt(i)) {
352	                count++;
353	            }
354	        }
355	        return count;
