508	    private void onFragmentLoaded(final boolean restoreScrollPosition) {
509	        if (recyclerAdapter == null) {
510	            MainActivity activity = (MainActivity) getActivity();
511	            recyclerAdapter = new QueueRecyclerAdapter(activity, itemAccess,
512	                new DefaultActionButtonCallback(activity), itemTouchHelper);
513	            recyclerAdapter.setHasStableIds(true);
514	            recyclerView.setAdapter(recyclerAdapter);
515	        }
516	        // The list must not be hidden (View.GONE) when it is empty: A hidden RecyclerView is
517	        // never laid out, so pending item animations (for example the removal of the last item
518	        // after a swipe) are never finished. Views of removed items would then stay attached,
519	        // keeping the translation that was applied while swiping. As a result, re-adding the
520	        // item (undo) would display it outside of the visible area.
521	        // Instead, the empty view is simply drawn on top of the (empty) list.
522	        txtvEmpty.setVisibility(queue == null || queue.size() == 0 ? View.VISIBLE : View.GONE);
523	        recyclerView.setVisibility(View.VISIBLE);
524	
525	        if (restoreScrollPosition) {
526	            restoreScrollPosition();
527	        }
528	
529	        // we need to refresh the options menu because it sometimes
530	        // needs data that may have just been loaded.
531	        getActivity().supportInvalidateOptionsMenu();
